import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`linkedin-post-leads`,heroTitle:`Turn LinkedIn engagement into leads in minutes`,heroSubtitle:`Perplexity Computer identifies the people who engaged (commenters and reshares), finds their company, title, and direct email address, and delivers a spreadsheet with each person's comment quoted and a personalized cold email that references their engagement.`,inputUrlCta:`Turn LinkedIn engagement into leads`,inputUrlPlaceholder:`https://www.linkedin.com/posts/...`,inputUrlPrefill:`Go to {url} and build this opportunity list. Use this brief as context: Paste the URL of a viral LinkedIn post in your industry. Computer identifies the people who engaged (commenters and reshares), finds their company, title, and direct email address, and delivers a spreadsheet with each person's comment quoted and a personalized cold email that references their engagement. (1) Analyze the business, audience, and targeting context. (2) Find the best-fit people, companies, or opportunities relevant to the brief. (3) Verify and rank each result by fit, quality, and likelihood to convert. (4) Draft tailored outreach or follow-up assets where useful. (5) Deliver a spreadsheet-ready list with the most important context and next steps.`,heroOverlaySteps:[`Analyzing the URL to understand the target profile and opportunity`,`Finding and ranking the best-fit opportunities for the workflow`,`Verifying fit signals and drafting useful outreach angles`,`Opportunity list and follow-up assets ready to use`],generatingSteps:[`Reviewing {url} to understand the targeting brief and goals`,`Designing an agent to search for the strongest opportunities and verify fit`,`Configuring ranking, filtering, and outreach support for the best matches`,`Packaging the work into a list the team can review and act on immediately`],featureSectionTitle:`From rough targeting to ranked opportunities`,featureCardTitles:[`Connects to your revenue workflow`,`Outputs your team can work from`],featureCardDescriptions:[`Computer breaks the work into focused tasks, spins up specialized agents, and matches each task to the model that fits it best.`,`Sheets, CRM tools, Docs, and outbound workflows stay in the loop so the work moves straight into the tools your team already uses.`,`Ranked opportunities. Verified context. Outreach angles. Computer gives you a list your team can start working from immediately.`],capabilitySectionTitle:`Your opportunity finder, on autopilot`,capabilitySectionSubtitle:`Paste your URL, step away, and come back to a ranked list your team can act on.`,capabilityCards:[{title:`Opportunity Discovery`,description:`Computer can search for relevant people, companies, channels, or placements that match the business and the targeting brief.`},{title:`Fit Verification`,description:`Computer can verify the context around each result and rank the strongest opportunities by quality and likely fit.`},{title:`Outreach Assets`,description:`Computer can draft useful outreach, follow-up, or contact notes so the team can move from list building to action faster.`},{title:`Connect Your Tools`,description:`Computer can organize the ranked list in Sheets, Docs, Notion, and other workflow tools so it is easy to review and share.`},{title:`Priority Ranking`,description:`Computer can sort the list by the opportunities most likely to convert so the team starts with the best options.`},{title:`Refresh the List`,description:`Computer can rerun the workflow later, surface new opportunities, and keep the list current as conditions change.`}]});export{t as default};
